import { config as serpApiConfig, getJson } from 'serpapi';
import http from 'node:http';
import net from 'node:net';

if (process.env.SERPAPI_BASE_URL) {
  const { hostname, port } = new URL(process.env.SERPAPI_BASE_URL);
  const agent = new http.Agent();
  agent.createConnection = (_options, callback) => net.createConnection({ host: hostname, port: Number(port) }, callback);
  serpApiConfig.requestOptions = { protocol: 'http:', agent };
}
